mapper.select:


WHERE 1 = 1

    AND b.id = #{branch.id}


    AND js.id = #{jobScheduler.id}


    AND co.id = #{commune.id}


    AND cn.id = #{country.id}



    AND UPPER(e.name) LIKE UPPER(#{_name})



    AND UPPER(e.last_name) LIKE UPPER(#{_lastName})



    AND UPPER(e.mother_last_name) LIKE UPPER(#{_motherLastName})


    AND e.gender_id = #{gender.id}


    AND e.marital_status_id = #{maritalStatus.id}


    AND e.contract_type_id = #{contractType.id}



    AND e.phone LIKE #{_phone}



    AND e.email LIKE #{_email}



    AND e.address LIKE #{_address}


    AND e.contract_date = #{contractDate}


    AND e.contract_end_date = #{contractEndDate}


    AND e.active = #{active}


    AND e.job_type_id = #{jobType.id}
